// Generates the Rust MCP allow-list from the one place tools are declared.
//
// Rust never interprets a tool name beyond matching it against the allow-list,
// so it has no reason to own that list. Keeping a hand-written copy on each
// side of the IPC boundary lets the two drift apart silently — one side ends up
// knowing tools the other does not. Run with `--check` to fail when the
// generated file is stale.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
);
const REGISTRY_PATH = path.join(
  repoRoot,
  "src",
  "lib",
  "visual-editor",
  "mcp-tool-registry.ts",
);
const GENERATED_PATH = path.join(
  repoRoot,
  "src-tauri",
  "src",
  "mcp_tool_names.rs",
);
/** A registry this small means the table shape changed and parsing silently failed. */
const MINIMUM_EXPECTED_TOOLS = 60;

function readRegistryToolNames() {
  const source = fs.readFileSync(REGISTRY_PATH, "utf8");
  const table = source.match(
    /export const XRIFT_MCP_TOOLS = \[([\s\S]*?)\n\] as const satisfies/,
  );
  if (!table) {
    throw new Error(
      `${path.relative(repoRoot, REGISTRY_PATH)} no longer contains an XRIFT_MCP_TOOLS table, so the Rust allow-list cannot be generated`,
    );
  }
  const names = [...table[1].matchAll(/\{\s*name:\s*"([a-z_]+)",\s*surface:/g)].map(
    (entry) => entry[1],
  );
  if (names.length < MINIMUM_EXPECTED_TOOLS) {
    throw new Error(
      `Parsed only ${names.length} tool names from the registry, which cannot be right`,
    );
  }
  const duplicates = names.filter((name, index) => names.indexOf(name) !== index);
  if (duplicates.length > 0) {
    throw new Error(`Duplicate tool names in the registry: ${duplicates.join(", ")}`);
  }
  return names;
}

function renderRustModule(names) {
  const entries = names.map((name) => `    "${name}",`).join("\n");
  return `// @generated by scripts/generate-mcp-tool-names.mjs — do not edit.
//
// Source of truth: src/lib/visual-editor/mcp-tool-registry.ts
// Regenerate with: pnpm mcp:tool-names

pub const MCP_TOOL_NAMES: [&str; ${names.length}] = [
${entries}
];
`;
}

const names = readRegistryToolNames();
const rendered = renderRustModule(names);
const checkOnly = process.argv.includes("--check");
const current = fs.existsSync(GENERATED_PATH)
  ? fs.readFileSync(GENERATED_PATH, "utf8")
  : "";

if (checkOnly) {
  if (current !== rendered) {
    console.error(
      `${path.relative(repoRoot, GENERATED_PATH)} is out of date with the MCP tool registry.\nRun: pnpm mcp:tool-names`,
    );
    process.exit(1);
  }
  console.log(`mcp tool names checked: ${names.length} tools`);
} else {
  fs.writeFileSync(GENERATED_PATH, rendered);
  console.log(
    `wrote ${path.relative(repoRoot, GENERATED_PATH)}: ${names.length} tools`,
  );
}
